def get_curated_dataset() -> "List[Tuple[str, List[int]]]":
    return CURATED_PHRASES


def get_label_distribution() -> "dict[str, int]":
    from collections import Counter
    counts: "dict[str, int]" = Counter()
    from src.model_config import LABELS
    for text, vec in CURATED_PHRASES:
        for i, v in enumerate(vec):
            if v:
                counts[LABELS[i]] += 1
    return dict(counts)
